<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, BookOpen, ChevronDown, MessageCircle, Minus, Network, Plus, RotateCcw, Target, Trash2, X } from '@lucide/vue'

type Node = { id: string; title: string; x: number; y: number; mastery: number; state: '已掌握' | '学习中' | '薄弱'; root?: boolean }
const router = useRouter(); const selected = ref<string | null>(null); const masteryFilter = ref('全部'); const zoom = ref(1); const filterOpen = ref(false); const removed = ref<string[]>([])
const nodes: Node[] = [{ id: 'ml', title: '机器学习基础', x: 42, y: 43, mastery: 78, state: '学习中', root: true }, { id: 'linear', title: '线性代数', x: 20, y: 24, mastery: 42, state: '薄弱' }, { id: 'eval', title: '模型评估', x: 22, y: 67, mastery: 68, state: '学习中' }, { id: 'cnn', title: 'CNN', x: 68, y: 20, mastery: 84, state: '已掌握' }, { id: 'transformer', title: 'Transformer', x: 74, y: 66, mastery: 73, state: '学习中' }, { id: 'backprop', title: '反向传播', x: 55, y: 84, mastery: 48, state: '薄弱' }]
const visibleNodes = computed(() => nodes.filter(node => !removed.value.includes(node.id) && (masteryFilter.value === '全部' || node.state === masteryFilter.value)))
const current = computed(() => nodes.find(node => node.id === selected.value))
const nodeClass = (node: Node) => node.state === '薄弱' ? 'weak' : node.state === '已掌握' ? 'mastered' : 'learning'
const removeNode = () => { if (current.value) { removed.value.push(current.value.id); selected.value = null } }
</script>

<template>
  <section class="graph-page"><div class="graph-inner">
    <header class="graph-header"><div><span class="eyebrow">探索你的知识结构</span><h1>知识图谱</h1><p>从对话、资源与练习中持续生长的个人知识网络</p></div><div class="graph-actions"><div class="filter-wrap"><button class="filter-button" @click="filterOpen=!filterOpen">{{ masteryFilter }} <ChevronDown :size="14" /></button><div v-if="filterOpen" class="filter-menu"><button v-for="item in ['全部','已掌握','学习中','薄弱']" :key="item" @click="masteryFilter=item;filterOpen=false">{{ item }}</button></div></div><button class="icon-button" title="放大" @click="zoom=Math.min(1.2,zoom+.1)"><Plus :size="16" /></button><button class="icon-button" title="缩小" @click="zoom=Math.max(.8,zoom-.1)"><Minus :size="16" /></button><button class="icon-button" title="重置视图" @click="zoom=1"><RotateCcw :size="15" /></button></div></header>
    <div class="graph-layout"><section class="canvas-panel"><div class="canvas-toolbar"><span><span class="legend-dot mastered" />已掌握</span><span><span class="legend-dot learning" />学习中</span><span><span class="legend-dot weak" />薄弱</span><small>{{ visibleNodes.length }} 个知识节点 · 18 条关联</small></div><div class="graph-canvas" :style="{ transform: `scale(${zoom})` }"><div class="edge edge-a"/><div class="edge edge-b"/><div class="edge edge-c"/><div class="edge edge-d"/><button v-for="node in visibleNodes" :key="node.id" class="graph-node" :class="[nodeClass(node),{active:selected===node.id,root:node.root}]" :style="{left:node.x+'%',top:node.y+'%'}" @click="selected=node.id"><span>{{ node.title }}</span><small>{{ node.mastery }}%</small></button><div v-if="!visibleNodes.length" class="filtered-empty">没有符合当前筛选的知识节点</div></div><div class="graph-footer"><span>点击节点查看详情 · 拖拽与缩放可在后续接入真实图谱</span><button @click="router.push('/question-nav-chat')"><MessageCircle :size="15" />向 AI 提问</button></div></section><aside v-if="current" class="node-panel"><div class="node-panel-head"><span class="eyebrow">知识节点详情</span><button @click="selected=null"><X :size="17" /></button></div><h2>{{ current.title }}</h2><div class="mastery-score"><strong>{{ current.mastery }}%</strong><span>{{ current.state }}</span></div><div class="mastery-bar"><i :style="{width:current.mastery+'%'}" /></div><p>这个知识点与你当前的学习路径相关，最近一次更新来自练习记录。</p><div class="node-actions"><button @click="router.push('/learning-path')"><BookOpen :size="15" />学这个</button><button @click="router.push('/exercise')"><Target :size="15" />做题</button><button @click="router.push('/question-nav-chat')"><MessageCircle :size="15" />提问</button><button class="danger-action" @click="removeNode"><Trash2 :size="15" />移除节点</button></div><div class="related"><span>关联知识点</span><button @click="selected='linear'">线性代数 <ArrowRight :size="13" /></button><button @click="selected='backprop'">反向传播 <ArrowRight :size="13" /></button></div></aside><aside v-else class="graph-empty"><Network :size="42" stroke-width="1.2" /><h2>选择一个知识节点</h2><p>点击图谱中的节点，查看掌握度、关联关系和下一步操作。</p></aside></div>
  </div></section>
</template>

